oxy_webhelp_navlinks = {"arch_recover_data_archival_locations-d39307e9604":{"topics":[{"title":"Recovery options from archival locations","shortdesc":"<p class=\"shortdesc\">Several recovery methods are available for data in archival locations, ranging from         single-file restore to full disaster recovery using a reader cluster.<\/p>","href":"archival\/arch_recovery_options.html","attributes":{"data-id":"arch_recovery_options"},"menu":{"hasChildren":false},"tocID":"arch_recovery_options-d39307e9615","topics":[]},{"title":"Recovering data from cloud archival locations","shortdesc":"<p class=\"shortdesc\">Restore workloads from snapshots stored in Azure, Amazon S3, or GCP archival         locations using the owner cluster or a connected reader cluster.<\/p>","href":"archival\/arch_recover_from_cloud_arch_loc.html","attributes":{"data-id":"arch_recover_from_cloud_arch_loc"},"menu":{"hasChildren":false},"tocID":"arch_recover_from_cloud_arch_loc-d39307e9626","topics":[]},{"title":"Recovering data from NFS archival locations","shortdesc":"<p class=\"shortdesc\">Restore workloads from snapshots stored in an NFS archival location using the owner         Rubrik cluster.<\/p>","href":"archival\/arch_recover_from_nfs_arch_loc.html","attributes":{"data-id":"arch_recover_from_nfs_arch_loc"},"menu":{"hasChildren":false},"tocID":"arch_recover_from_nfs_arch_loc-d39307e9637","topics":[]},{"title":"Data recovery using another Rubrik cluster","shortdesc":"<p class=\"shortdesc\">Rubrik CDM supports connecting a different Rubrik cluster to an existing archival     location as a reader, enabling data recovery from archived snapshots when the primary cluster is     unavailable.<\/p>","href":"archival\/arch_disaster_recovery_using_arch_loc.html","attributes":{"data-id":"arch_disaster_recovery_using_arch_loc"},"menu":{"hasChildren":false},"tocID":"arch_disaster_recovery_using_arch_loc-d39307e9648","next":"arch_disaster_recovery_using_arch_loc-d39307e9648"}]}};